CREATE TABLE standard_vehicle_layouts(vehicle_id TEXT PRIMARY KEY REFERENCES vehicles(id),layout_json TEXT NOT NULL CHECK(json_valid(layout_json)),revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE standard_departure_layouts(departure_id TEXT PRIMARY KEY REFERENCES departures(id),capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 100),layout_json TEXT CHECK(layout_json IS NULL OR json_valid(layout_json)));
INSERT INTO standard_departure_layouts(departure_id,capacity) SELECT id,(SELECT capacity FROM vehicles WHERE id=departures.vehicle_id) FROM departures;
CREATE TRIGGER ground_departure_layout AFTER INSERT ON departures BEGIN INSERT INTO standard_departure_layouts(departure_id,capacity,layout_json) SELECT NEW.id,v.capacity,l.layout_json FROM vehicles v LEFT JOIN standard_vehicle_layouts l ON l.vehicle_id=v.id WHERE v.id=NEW.vehicle_id; END;
CREATE TRIGGER ground_layout_claim BEFORE INSERT ON seat_claims WHEN NEW.status IN('held','confirmed') AND (NEW.seat_number>(SELECT capacity FROM standard_departure_layouts WHERE departure_id=NEW.departure_id) OR EXISTS(SELECT 1 FROM standard_departure_layouts l,json_each(l.layout_json,'$.seats') s WHERE l.departure_id=NEW.departure_id AND json_extract(s.value,'$.number')=NEW.seat_number AND json_extract(s.value,'$.blocked')=1)) BEGIN SELECT RAISE(ABORT,'seat_unavailable'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0035_vehicle_seating');
